<div class="flex flex-col col-span-full sm:col-span-6 w-[1200px] mx-auto bg-white dark:bg-gray-800 shadow-sm rounded-xl overflow-hidden">
    <!-- Encabezado -->
    <header class="relative px-5 py-4 border-b border-gray-100 dark:border-gray-700/60 flex flex-col sm:flex-row items-center justify-between gap-4"> 
        <div class="flex items-center gap-4">
            <h2 class="font-semibold text-gray-800 dark:text-gray-100 uppercase tracking-widest text-sm sm:text-base">SEMAFORO POSTAL</h2>
            <select id="tipo-oficina-filter" class="border-gray-300 dark:border-gray-600 rounded-lg shadow-sm text-[11px] font-bold py-1.5 px-3 focus:ring-blue-500 focus:border-blue-500 w-28 bg-white dark:bg-gray-700 dark:text-gray-100 transition-all hover:border-gray-400 cursor-pointer uppercase">
                <option value="opt">OPT</option>
                <option value="cop">COP</option>
            </select>
        </div>
        
        <div class="flex items-center gap-2 flex-wrap">
            <a href="{{ route('paquetes-por-oficina') }}"
            target="_blank"
            class="bg-[#6b1820] hover:bg-[#7b1f27] text-white text-[11px] font-bold px-4 py-2 rounded-lg transition-all shadow-sm flex items-center gap-2 group whitespace-nowrap">
                <span>PAQUETES POR OFICINA</span>
                <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4 transition-transform group-hover:scale-110" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                </svg>
            </a>

            <a href="/semaforo-postal"
            target="_blank"
            class="bg-[#1a234e] hover:bg-cyan-600 text-white text-[11px] font-bold px-4 py-2 rounded-lg transition-all shadow-sm flex items-center gap-2 group whitespace-nowrap">
                <span>VER DETALLE COMPLETO</span>
                <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4 transition-transform group-hover:scale-110" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                </svg>
            </a>
        </div>
    </header>

    <div class="flex flex-col md:flex-row flex-1 min-h-0">
        <div class="flex-1 p-4">
            <div id="paper" class="relative" style="width: 800px; height: 600px; overflow: hidden;">
                <img src="images\guyana.png" 
                    alt="Esequibo" 
                    id="map-image"
                    class="absolute"
                    style="top: 35%; 
                            right: 5%;  
                            width: 158px; 
                            height: auto; 
                            opacity: 0.8;
                            z-index: 10;">
            </div>
        </div>
        <div class="w-full md:w-1/3 border-t md:border-t-0 md:border-l border-gray-200 dark:border-gray-700 p-4 bg-gray-50 dark:bg-gray-700/30 overflow-y-auto">
            <div id="state-info-panel">
                <div class="flex justify-between items-center mb-2">
                    <h3 id="state-name" class="text-lg font-medium text-gray-900 dark:text-gray-100 italic">NACIONAL</h3>
                </div>
                <div id="offices-container">
                    <p class="text-gray-500 dark:text-gray-400">Seleccione un estado para ver sus oficinas</p>
                </div>
                <div id="percentage-container" class="mt-4">
                    <p class="text-gray-500 dark:text-gray-400">Cargando porcentajes...</p>
                </div>
            </div>
        </div>
    </div>
    
    <!-- Tabla de estados y oficinas abiertas (oculta, conservada para no romper updateSummaryTable) -->
    <div class="p-4 border-t border-gray-200 dark:border-gray-700" hidden>
        <h3 class="text-lg font-medium text-gray-900 dark:text-gray-100 mb-4">Resumen de Oficinas por Estado</h3>
        <div class="overflow-x-auto">
            <table id="offices-summary-table" class="min-w-full divide-y divide-gray-200 dark:divide-gray-700 text-sm">
                <thead class="bg-gray-50 dark:bg-gray-700">
                    <tr>
                        <th scope="col" class="px-4 py-2 text-left font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">Estado</th>
                        <th scope="col" class="px-4 py-2 text-left font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">Abiertas</th>
                        <th scope="col" class="px-4 py-2 text-left font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">Cerradas</th>
                    </tr>
                </thead>
                <tbody class="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">

                </tbody>
            </table>
        </div>
    </div>

    <style>
        #paper {
            position: relative;
            margin: 0 auto;
        }

        #map-image {
            transition: transform 0.2s ease;
            will-change: transform;
        }

        @media (max-width: 768px) {
            #paper {
                width: 100% !important;
                height: 400px !important;
            }
            
            #map-image {
                right: 5% !important;  <!-- Ajuste para móviles -->
                top: 35% !important;
                width: 120px !important;
                max-width: 25vw !important;
            }
        }
    </style>
</div>


