            const estadosData = {
        "capital": {id: 1, nombre: "Distrito Capital"},
        "miranda": {id: 2, nombre: "Miranda"},
        "barinas": {id: 3, nombre: "Barina"},
        "trujillo": {id: 4, nombre: "Trujillo"},
        "merida": {id: 5, nombre: "Merida"},
        "tachira": {id: 6, nombre: "Tachira"},
        "carabobo": {id: 7, nombre: "Carabobo"},
        "cojedes": {id: 8, nombre: "Cojedes"},
        "lara": {id: 9, nombre: "Lara"},
        "portuguesa": {id: 10, nombre: "Portuguesa"},
        "yaracuy": {id: 11, nombre: "Yaracuy"},
        "amazonas": {id: 12, nombre: "Amazonas"},
        "apure": {id: 13, nombre: "Apure"},
        "aragua": {id: 14, nombre: "Aragua"},
        "guarico": {id: 15, nombre: "Guarico"},
        "falcon": {id: 16, nombre: "Falcón"},
        "zulia": {id: 17, nombre: "Zulia"},
        "anzoategui": {id: 18, nombre: "Anzoátegui"},
        "bolivar": {id: 19, nombre: "Bolívar"},
        "amacuro": {id: 20, nombre: "Delta Amacuro"},
        "monagas": {id: 21, nombre: "Monagas"},
        "nuevaesparta": {id: 22, nombre: "Nueva Esparta"},
        "sucre": {id: 23, nombre: "Sucre"},
        "vargas": {id: 24, nombre: "La Guaira"}
    };
    var currentState = null; 
    var activeColor = "#4CAF50";
    var inactiveColor = "#F44336";
    var neutralColor = "#FFFFFF";
    var highlightColor = "#2196F3";

    function colorizeStates() {
        // Un solo request: el backend devuelve el color ya resuelto por estado
        // (antes se hacía un fetch por cada estado → 26 peticiones).
        const colorMap = { verde: activeColor, rojo: inactiveColor, blanco: neutralColor };

        fetch('/mapaColores')
            .then(response => response.json())
            .then(data => {
                for (const state in ven) {
                    const estadoInfo = estadosData[state];
                    if (!estadoInfo) continue;
                    const info = data[estadoInfo.id];
                    // Estado sin oficinas o no autorizado → neutro.
                    const fillColor = info ? (colorMap[info.color] || neutralColor) : neutralColor;
                    ven[state].attr({ fill: fillColor });
                }
            })
            .catch(error => {
                console.error('Error cargando colores del mapa:', error);
            });
    }
    var currentOfficesData = null;
    // Bandera: indica que el usuario seleccionó un estado no autorizado (403).
    // Evita que el auto-refresco nacional repinte el panel encima del aviso "Acceso restringido".
    var estadoBloqueado = false;

    document.getElementById('tipo-oficina-filter').addEventListener('change', function() {
        renderOfficesList();
    });

    function renderOfficesList() {
        const officesContainer = document.getElementById('offices-container');
        const filterValue = document.getElementById('tipo-oficina-filter').value;
        const data = currentOfficesData;

        if (!data || !data.Nombre || data.Nombre.length === 0) {
            officesContainer.innerHTML = `
                <div class="text-center py-4">
                    <svg class="mx-auto h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                    </svg>
                    <h3 class="mt-2 text-sm font-medium text-gray-900 dark:text-gray-100">No hay oficinas registradas</h3>
                </div>
            `;
            return;
        }

        let filteredIndices = [];
        data.Nombre.forEach((nombre, index) => {
            const tipo = data.Tipo ? data.Tipo[index] : null;
            let include = false;
            if (filterValue === 'opt') {
                include = [1, 2, 3].includes(Number(tipo));
            } else if (filterValue === 'cop') {
                include = Number(tipo) === 4;
            }
            if (include) {
                filteredIndices.push(index);
            }
        });

        const percentageContainer = document.getElementById('percentage-container');

        if (filteredIndices.length > 0) {
            let activeCount = 0;
            let inactiveCount = 0;
            let officesHTML = `
                <div class="mb-2">
                    <h4 class="font-medium text-gray-800 dark:text-gray-200 mb-2">
                        Oficinas (${filteredIndices.length})
                    </h4>
                    <div class="max-h-96 overflow-y-auto border dark:border-gray-700 rounded-md">
                        <ul class="divide-y divide-gray-200 dark:divide-gray-700">
            `;
            
            filteredIndices.forEach(index => {
                const nombre = data.Nombre[index];
                const isActive = data.Operaciones[index];
                if (isActive) activeCount++; else inactiveCount++;

                officesHTML += `
                    <li class="py-2 px-3 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                        <div class="flex items-center">
                            <span class="w-6 text-center ${isActive ? 'text-green-500' : 'text-red-500'}">
                                ${isActive ? '✓' : '✗'}
                            </span>
                            <span class="ml-2 text-sm font-medium text-gray-800 dark:text-gray-200">${nombre}</span>
                        </div>
                    </li>
                `;
            });
            
            officesHTML += `
                        </ul>
                    </div>
                    <div class="mt-2 text-xs text-gray-500 dark:text-gray-400">
                        <span class="text-green-500 font-semibold">${activeCount} operativas</span> | 
                        <span class="text-red-500 font-semibold">${inactiveCount} cerradas</span>
                    </div>
                </div>
            `;
            officesContainer.innerHTML = officesHTML;

            const totalFiltered = filteredIndices.length;
            const abiertasPercentage = ((activeCount / totalFiltered) * 100).toFixed(2);
            const cerradasPercentage = ((inactiveCount / totalFiltered) * 100).toFixed(2);
            const color = abiertasPercentage >= 50 ? (abiertasPercentage == 50 ? 'text-yellow-500' : 'text-green-500') : 'text-red-500';

            percentageContainer.innerHTML = `
                <div class="flex justify-between items-center bg-white dark:bg-gray-800 p-3 rounded-lg shadow-sm border border-gray-100 dark:border-gray-700">
                    <div class="flex flex-col">
                        <span class="text-[10px] uppercase text-gray-500 dark:text-gray-400 font-bold tracking-tighter">Abiertas</span>
                        <span class="text-sm font-bold ${color}">${abiertasPercentage}%</span>
                    </div>
                    <div class="flex flex-col text-right">
                        <span class="text-[10px] uppercase text-gray-500 dark:text-gray-400 font-bold tracking-tighter">Cerradas</span>
                        <span class="text-sm font-bold text-red-500">${cerradasPercentage}%</span>
                    </div>
                </div>
            `;
        } else {
            officesContainer.innerHTML = `
                <div class="text-center py-8">
                    <svg class="mx-auto h-12 w-12 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                    </svg>
                    <p class="mt-2 text-sm text-gray-500 dark:text-gray-400">No hay oficinas de este tipo disponibles.</p>
                </div>
            `;
            percentageContainer.innerHTML = `
                <div class="text-center py-2 bg-gray-50 dark:bg-gray-800/50 rounded-lg">
                    <span class="text-[11px] text-gray-500 dark:text-gray-400 italic">Sin datos para filtrar</span>
                </div>
            `;
        }
    }

    function showOffices(stateId, stateName) {
        const officesContainer = document.getElementById('offices-container');
        officesContainer.innerHTML = `
            <div class="flex flex-col items-center justify-center py-10">
                <div class="animate-spin h-8 w-8 text-blue-500 mb-4"></div>
                <span class="text-sm font-medium text-gray-600 dark:text-gray-400">Consultando oficinas...</span>
            </div>
        `;

        fetch(`/mapaOficinas/${stateId}`)
            .then(response => response.json().then(data => ({ status: response.status, ok: response.ok, data })))
            .then(({ status, ok, data }) => {
                // Validación: el gerente de estado no puede ver información de otro estado (backend responde 403).
                if (status === 403) {
                    currentOfficesData = null;
                    estadoBloqueado = true; // bloquea el auto-refresco para que no borre este aviso
                    officesContainer.innerHTML = `
                        <div class="rounded-md bg-amber-50 border border-amber-200 p-4">
                            <div class="flex">
                                <div class="flex-shrink-0">
                                    <svg class="h-5 w-5 text-amber-500" viewBox="0 0 20 20" fill="currentColor">
                                        <path fill-rule="evenodd" d="M10 1a4.5 4.5 0 00-4.5 4.5V9H5a2 2 0 00-2 2v6a2 2 0 002 2h10a2 2 0 002-2v-6a2 2 0 00-2-2h-.5V5.5A4.5 4.5 0 0010 1zm3 8V5.5a3 3 0 10-6 0V9h6z" clip-rule="evenodd"></path>
                                    </svg>
                                </div>
                                <div class="ml-3">
                                    <h3 class="text-sm font-medium text-amber-800">Acceso restringido</h3>
                                    <div class="mt-2 text-sm text-amber-700">
                                        <p>Solo puede consultar la información de las oficinas de su estado.</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;
                    document.getElementById('percentage-container').innerHTML = '';
                    return;
                }

                if (ok && data && data.Nombre && data.Operaciones && data.Nombre.length === data.Operaciones.length) {
                    estadoBloqueado = false; // estado autorizado: se reactiva el flujo normal
                    currentOfficesData = data;
                    renderOfficesList();
                    return;
                }

                // Estado sin oficinas registradas (backend responde 404) u otra respuesta sin datos válidos.
                if (status === 404) {
                    estadoBloqueado = false;
                    currentOfficesData = null;
                    officesContainer.innerHTML = `
                        <div class="text-center py-8">
                            <svg class="mx-auto h-12 w-12 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                            </svg>
                            <p class="mt-2 text-sm text-gray-500 dark:text-gray-400">No hay oficinas registradas para este estado.</p>
                        </div>
                    `;
                    document.getElementById('percentage-container').innerHTML = '';
                    return;
                }

                throw new Error("Formato de datos incorrecto");
            })
            .catch(error => {
                // Validación de error genérico: fallo de red o del servidor.
                console.error('Error al cargar oficinas del mapa:', error);
                officesContainer.innerHTML = `
                    <div class="rounded-md bg-red-50 p-4">
                        <div class="flex">
                            <div class="flex-shrink-0">
                                <svg class="h-5 w-5 text-red-400" viewBox="0 0 20 20" fill="currentColor">
                                    <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293-1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clip-rule="evenodd"></path>
                                </svg>
                            </div>
                            <div class="ml-3">
                                <h3 class="text-sm font-medium text-red-800">Error al cargar oficinas</h3>
                                <div class="mt-2 text-sm text-red-700">
                                    <p>Ocurrió un error al consultar la información. Intente nuevamente más tarde.</p>
                                </div>
                            </div>
                        </div>
                    </div>
                `;
                document.getElementById('percentage-container').innerHTML = '';
            });
    }

    function loadInitialNationalData() {
        // Si el usuario está viendo el aviso de un estado no autorizado, no tocar el panel.
        if (estadoBloqueado) {
            return;
        }

        const officesContainer = document.getElementById('offices-container');
        officesContainer.innerHTML = `
            <div class="flex flex-col items-center justify-center py-10">
                <div class="animate-spin h-8 w-8 text-blue-500 mb-4"></div>
                <span class="text-sm font-medium text-gray-600 dark:text-gray-400">Cargando oficinas nacionales...</span>
            </div>
        `;

        fetch('/oficinatabla', { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
            .then(response => response.json())
            .then(data => {
                if (estadoBloqueado) {
                    return; // el usuario seleccionó un estado bloqueado mientras cargaba: no repintar
                }
                if (data && Array.isArray(data)) {
                    // Convertir el formato de array de objetos al formato que usa renderOfficesList
                    currentOfficesData = {
                        Nombre: data.map(o => o.nombre),
                        Operaciones: data.map(o => o.operaciones === true || o.operaciones === 1),
                        Tipo: data.map(o => o.tipo_oficina_id),
                        status: "200"
                    };
                    renderOfficesList();
                }
            })
            .catch(error => {
                console.error('Error al cargar datos iniciales:', error);
                officesContainer.innerHTML = `<p class="text-red-500 text-sm p-4 text-center">Error al conectar con el servidor.</p>`;
            });
    }

    loadInitialNationalData();
    setInterval(loadInitialNationalData, 300000);

    for (var state in ven) {
        (function(st, stateName) {
            st[0].onclick = function() {
                const estadoInfo = estadosData[stateName];
                

                if (currentState) {
                    ven[currentState].animate({stroke: "#666", "stroke-width": 1}, 300);
                }
                
                st.animate({stroke: highlightColor, "stroke-width": 2}, 300);
                st.toFront();
                currentState = stateName;

                document.getElementById('state-name').textContent = estadoInfo.nombre;
                showOffices(estadoInfo.id, estadoInfo.nombre);
            };
        })(ven[state], state);
    }
    function updateSummaryTable() {
    const tableBody = document.querySelector('#offices-summary-table tbody');
    tableBody.innerHTML = '<tr><td colspan="4" class="text-center py-4"><div class="animate-spin mx-auto h-5 w-5 text-blue-500"></div> Cargando datos...</td></tr>';

    fetch('/oficinatabla', { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
        .then(response => response.json())
        .then(data => {
            tableBody.innerHTML = ''; 
        
            const oficinasPorEstado = {};
            
            data.forEach(oficina => {
                if (!oficinasPorEstado[oficina.estado_id]) {
                    oficinasPorEstado[oficina.estado_id] = {
                        operaciones: 0,
                        nooperaciones: 0,
                        total: 0,
                        motivos: {}
                    };
                }
                
                if (oficina.operaciones === true) {
                    oficinasPorEstado[oficina.estado_id].operaciones++;
                } else {
                    oficinasPorEstado[oficina.estado_id].nooperaciones++;

                    const motivo = oficina.motivo_cierre || 'Sin motivo especificado';
                    if (!oficinasPorEstado[oficina.estado_id].motivos[motivo]) {
                        oficinasPorEstado[oficina.estado_id].motivos[motivo] = 0;
                    }
                    oficinasPorEstado[oficina.estado_id].motivos[motivo]++;
                }
                oficinasPorEstado[oficina.estado_id].total++;
            });

            const estadosOrdenados = Object.values(estadosData).sort((a, b) => a.nombre.localeCompare(b.nombre));
            
            estadosOrdenados.forEach(estado => {
                const conteoEstado = oficinasPorEstado[estado.id] || {
                    operaciones: 0,
                    nooperaciones: 0,
                    total: 0,
                    motivos: {}
                };
                
                const row = document.createElement('tr');
                row.className = 'hover:bg-gray-50 dark:hover:bg-gray-700';
                row.innerHTML = `
                    <td class="px-4 py-2 text-gray-800 dark:text-gray-200 font-medium">${estado.nombre}</td>
                    <td class="px-4 py-2 text-green-600 dark:text-green-400">${conteoEstado.operaciones}</td>
                    <td class="px-4 py-2 text-red-600 dark:text-red-400">${conteoEstado.nooperaciones}</td>

                `;
                
                const detailRow = document.createElement('tr');
                detailRow.className = 'hidden bg-gray-50 dark:bg-gray-700';
                let motivosHTML = '<td colspan="4" class="px-4 py-2"><div class="pl-4">';
                
                if (conteoEstado.nooperaciones > 0) {
                    motivosHTML += '<p class="font-medium text-gray-700 dark:text-gray-300 mb-1">Motivos de cierre:</p><ul class="list-disc pl-5">';
                    
                    for (const [motivo, cantidad] of Object.entries(conteoEstado.motivos)) {
                        motivosHTML += `<li class="text-sm text-gray-600 dark:text-gray-400">${motivo}</li>`;
                    }
                    
                    motivosHTML += '</ul>';
                } else {
                    motivosHTML += '<p class="text-sm text-gray-500 dark:text-gray-400">Todas las oficinas están operaciones</p>';
                }
                
                motivosHTML += '</div></td>';
                detailRow.innerHTML = motivosHTML;
            
                row.addEventListener('click', () => {
        
                    detailRow.classList.toggle('hidden');
                    
                
                    const stateElement = ven[Object.keys(estadosData).find(key => estadosData[key].id === estado.id)];
                    if (stateElement) {
                        stateElement.click();
                    }
                });
                row.style.cursor = 'pointer';
                
                tableBody.appendChild(row);
                tableBody.appendChild(detailRow);
            });
        })
        .catch(error => {
            tableBody.innerHTML = `
                <tr>
                    <td colspan="4" class="px-4 py-2 text-center text-red-600 dark:text-red-400">
                        Error al cargar los datos. Intente recargar la página.
                    </td>
                </tr>
            `;
            console.error('Error al cargar datos para la tabla:', error);
        });
}
updateSummaryTable();
colorizeStates();
};
</script> 
@endpush
